let terrainVertices=null,terrainCells=null;
function loadTerrain(){if(terrainCells)return;terrainCells=new Map();const data=CIRCUIT.elevation?.terrain;if(!data)return;const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));terrainVertices=new Float32Array(bytes.buffer);const v=terrainVertices;for(let i=0;i<v.length;i+=9){const minX=Math.floor(Math.min(v[i],v[i+3],v[i+6])/60),maxX=Math.floor(Math.max(v[i],v[i+3],v[i+6])/60),minZ=Math.floor(Math.min(v[i+2],v[i+5],v[i+8])/60),maxZ=Math.floor(Math.max(v[i+2],v[i+5],v[i+8])/60);for(let x=minX;x<=maxX;x++)for(let z=minZ;z<=maxZ;z++){const key=x+':'+z;if(!terrainCells.has(key))terrainCells.set(key,[]);terrainCells.get(key).push(i)}}}
