// Solo race-weekend integration; multiplayer keeps its server-authoritative session lifecycle.
const GP={weekend:null,models:[],lastHUD:0,qualAdvance:false,pitChoice:'hard',lastValid:true};
function gpConfig(){const lapsValue=$('gp-length').value,full=Math.floor((CIRCUIT.id==='monaco'?260000:305000)/LEN)+1;return{length:LEN,speed:racingGuide.speed,ds:CIRCUIT.line.ds,left:CIRCUIT.widthLeft,right:CIRCUIT.widthRight,lineOffset:CIRCUIT.line.offset,baseLap:racingGuide.report.time,pit:PIT,pitExitOffset:prog(PIT.x.at(-1),PIT.z.at(-1),-1).d-RaceWeekend.interp(CIRCUIT.line.offset,PIT.exit),difficulty:$('gp-difficulty').value,qualifying:$('gp-qualifying').value,laps:lapsValue==='full'?full:Number(lapsValue),twoCompounds:$('gp-strategy').checked,startTyre:$('gp-start-tyre').value}}
const baseNewSession=newSession,baseFinish=finish,baseTiming=timing;
newSession=function(m){if(typeof MP!=='undefined'&&MP.active&&m!=='mp')return;if(m==='qual'||m==='gp'){startWeekend(m);return}clearWeekend();baseNewSession(m)};
finish=function(){if(GP.weekend){if(GP.weekend.phase==='qualifying'){GP.weekend.expired=true;GP.weekend.endQual();gpResults()}else{GP.weekend.player.retired=true;GP.weekend.player.finished=true;GP.weekend.player.finishTime=GP.weekend.clock;gpResults(true)}return}baseFinish()};
timing=function(pi){if(GP.weekend)return;baseTiming(pi)};
function clearWeekend(){GP.weekend=null;for(const m of GP.models)m.visible=false;$('gp-timing').hidden=true;$('gp-race-strip').hidden=true;document.body.classList.remove('weekend-driving')}
function makeRaceModels(){if(GP.models.length)return;for(let id=1;id<22;id++){const mesh=car.clone(true);mesh.name='MR 26 competitor '+id;mesh.traverse(o=>{if(o.isMesh)o.castShadow=true});mesh.visible=false;scene.add(mesh);GP.models.push(mesh)}}
function startWeekend(m,existing=false){if(!existing){GP.weekend=new RaceWeekend.Weekend(gpConfig());GP.pitChoice='hard'}const w=GP.weekend;baseNewSession(m);makeRaceModels();mode=m;for(const m of GP.models)m.visible=true;if(m==='qual'){w.startQual(existing?w.stage+1:0);state='race';show('none');const pose=w.pitPose(w.player);gpPlace(pose);race.cd=0}else{w.startRace();const p=w.player;gpPlace(gpTrackPose(p));race.cd=7.2+((Date.now()%1300)/1000);state='count';show('count')}race.started=true;race.lapNo=1;race.valid=true;acc=0;$('gp-timing').hidden=false;$('gp-race-strip').hidden=false;document.body.classList.add('weekend-driving');$('hud').hidden=false;gpHud(true)}
function gpPlace(p){Object.assign(c,{x:p.x,z:p.z,h:p.h,vx:0,vy:0,r:0,st:0});const pr=prog(c.x,c.z,-1);c.idx=pr.i;c.d=pr.d;snap=true}
function gpTrackPose(d){
 const f=RaceWeekend.mod(d.progress,LEN)/LEN*N,i=Math.floor(f),u=f-i,wrap=n=>(n+N)%N;
 // Cubic Hermite position and its analytic tangent remove polygonal yaw steps.
 const sample=(values)=>{const a=values[i],b=values[wrap(i+1)],m=(b-values[wrap(i-1)])*.5,n=(values[wrap(i+2)]-a)*.5;return{v:(2*u**3-3*u*u+1)*a+(u**3-2*u*u+u)*m+(-2*u**3+3*u*u)*b+(u**3-u*u)*n,d:(6*u*u-6*u)*a+(3*u*u-4*u+1)*m+(-6*u*u+6*u)*b+(3*u*u-2*u)*n}};
 const X=sample(CIRCUIT.line.x),Z=sample(CIRCUIT.line.z),len=Math.hypot(X.d,Z.d),nnx=-Z.d/len,nnz=X.d/len;
 const offset=clamp(d.offset,-trackHalf(f,-1)+1.05-RaceWeekend.interp(CIRCUIT.line.offset,f),trackHalf(f,1)-1.05-RaceWeekend.interp(CIRCUIT.line.offset,f));
 const x=X.v+nnx*offset,z=Z.v+nnz*offset,h=Math.atan2(Z.d,X.d)+Math.atan2(d.lateralV||0,Math.max(8,d.v));
 return{x,z,y:roadHeightAt(x,z,i),h,f,offset};
}

function gpPitRequest(){const w=GP.weekend;if(!w||state!=='race')return;w.requestPit(0,GP.pitChoice);msg(w.player.requested?'BOX THIS LAP · '+RaceWeekend.TYRES[GP.pitChoice].name:'PIT CALL CANCELLED',1800)}
function gpCycleTyre(){GP.pitChoice=['soft','medium','hard'][(['soft','medium','hard'].indexOf(GP.pitChoice)+1)%3];if(GP.weekend?.player.requested)GP.weekend.player.nextTyre=GP.pitChoice;gpHud(true)}
addEventListener('keydown',e=>{if(e.repeat||!GP.weekend||state!=='race')return;if(e.code==='KeyP'){e.preventDefault();gpPitRequest()}if(e.code==='KeyT'){e.preventDefault();gpCycleTyre()}});
function gpStepBefore(dt){const w=GP.weekend;if(!w)return false;const p=w.player;if(p.pit||p.finished||w.phase==='qualifying'&&p.stageDone){const wasPit=!!p.pit;w.update(dt);if(p.pit||wasPit){const pose=p.pit?w.pitPose(p):p.lastPitPose;c.x=pose.x;c.z=pose.z;c.h=pose.h;c.vx=p.v;c.vy=c.r=c.st=0;c.idx=Math.round(RaceWeekend.mod(p.progress,LEN)/LEN*N)%N;c.d=prog(c.x,c.z,c.idx).d;inp.t=p.v>0?.35:0;inp.b=p.v===0?1:0;}else{c.vx=0;inp.t=inp.b=0}race.t=w.clock;gpEvents();return true}return false}
function gpStepAfter(dt){const w=GP.weekend;if(!w)return;const pr=prog(c.x,c.z,c.idx),valid=Math.abs(pr.d)<=trackHalf(pr.i,Math.sign(pr.d))+.8;w.updatePlayer(pr.s/LEN*N,c.vx,dt,valid);w.player.offset=pr.d-RaceWeekend.interp(CIRCUIT.line.offset,pr.s/LEN*N);w.update(dt);race.t=w.clock;race.lapNo=Math.max(1,w.player.laps+1);race.lapStart=w.player.lapStart;race.valid=w.player.valid;race.best=w.player.best*1000;race.dist=Math.max(0,w.player.progress);if(w.phase==='race')gpContact();gpEvents()}
function gpEvents(){const w=GP.weekend;if(!w)return;for(const event of w.events.splice(0)){if(event.type==='pit-entry'){const d=w.drivers[event.id],p=event.id===0?{x:c.x,z:c.z,h:c.h,y:roadHeightAt(c.x,c.z,c.idx)}:gpTrackPose(d.previous?{...d,...d.previous}:d);if(d.pit)d.pit.entryPose=p;}if(event.type==='qualifying-end'||event.type==='race-end')gpResults();else if(event.id===0){if(event.type==='pit-service')msg('TYRES ON · '+RaceWeekend.TYRES[event.tyre].name,1800);if(event.type==='penalty')msg('+'+event.seconds+' SEC · '+event.reason,2400);if(event.type==='finished')msg(event.dsq?'CHEQUERED FLAG · TYRE RULE NOT MET':'CHEQUERED FLAG',3000);if(event.type==='lap'){race.last=event.time*1000;msg('LAP '+fmt(race.last),1500)}}}}
function gpRender(){const w=GP.weekend;if(!w)return;const alpha=state==='race'?clamp(acc/H,0,1):1;
 GP.models.forEach((mesh,i)=>{const d=w.drivers[i+1];mesh.visible=d.active&&!d.stageDone&&!d.finished&&(!d.pit||w.clock>=d.pit.release);if(!mesh.visible)return;
  const previous=d.previous;let view=d;if(previous&&!!previous.pit===!!d.pit){view={...d,progress:previous.progress+(d.progress-previous.progress)*alpha,offset:previous.offset+(d.offset-previous.offset)*alpha,v:previous.v+(d.v-previous.v)*alpha};if(d.pit)view.pit={...d.pit,s:previous.pit.s+(d.pit.s-previous.pit.s)*alpha}}
  const p=view.pit?w.pitPose(view):gpTrackPose(view);mesh.position.set(p.x,p.y+.025,p.z);mesh.rotation.set(view.pit?0:-bankAt(p.f),-p.h,view.pit?0:roadPitchAt(p.x,p.z,p.h,Math.floor(p.f)%N),'YXZ');const distance=mesh.position.distanceToSquared(car.position);mesh.visible=distance<1200**2;
  if(!mesh.userData.raceParts){const parts=[],spins=[];mesh.traverse(o=>{if(o.isMesh)parts.push(o);if(o.userData.wheelSpin)spins.push(o)});mesh.userData.raceParts=parts;mesh.userData.raceSpins=spins}
  const cast=distance<110**2;if(mesh.userData.shadowNear!==cast){for(const part of mesh.userData.raceParts)part.castShadow=cast;mesh.userData.shadowNear=cast}
  for(const spin of mesh.userData.raceSpins)spin.rotation.z=-view.progress/.37;
 });animatePitCrew(w);gpHud()}

function gpHud(force=false){const w=GP.weekend;if(!w)return;const now=performance.now();if(!force&&now-GP.lastHUD<130)return;GP.lastHUD=now;const p=w.player,qual=w.phase.startsWith('qualifying'),order=w.standings(),pos=order.findIndex(d=>d.id===0)+1;const remaining=Math.max(0,w.duration-w.clock),mins=Math.floor(remaining/60),secs=Math.floor(remaining%60);$('session-type').textContent=qual?(w.cfg.qualifying==='full'?'Q'+(w.stage+1):'QUALIFYING'):'RACE';$('lap').textContent=qual?(w.expired?'CHEQUERED FLAG':mins+':'+String(secs).padStart(2,'0')):'LAP '+Math.min(w.cfg.laps,Math.max(1,Math.floor(Math.max(0,p.progress)/LEN)+1))+' / '+w.cfg.laps;$('val').textContent=p.pit?(p.pit.hold?'TYRE SERVICE':'PIT LIMIT '+PIT.speedLimitKmh+' KM/H'):qual?(p.outlap?'OUT LAP':p.valid?'PUSH LAP':'LAP DELETED'):(p.penalty?'+'+p.penalty+' SEC PENALTY':'P'+pos+' / 22');$('val').className=qual&&!p.valid?'bad':'';
 const first=order[0];const rows=order.slice(0,5);if(!rows.some(d=>d.id===0))rows.push(p);$('gp-timing').innerHTML='<div class="gp-table-head">'+(qual?'CLASSIFICATION':'RACE ORDER')+'</div>'+rows.map(d=>{const position=order.indexOf(d)+1,time=qual?(Number.isFinite(d.best)?fmt(d.best*1000):'NO TIME'):(d.finished?'FINISHED':d.pit?'PIT':position===1?'LEADER':'+'+Math.max(0,(first.progress-d.progress)/Math.max(20,first.v)).toFixed(1));return '<div class="gp-row '+(d.id===0?'you':'')+'"><b>'+position+'</b><span>'+d.name+'</span><em style="color:'+RaceWeekend.TYRES[d.tyre].colour+'">'+RaceWeekend.TYRES[d.tyre].letter+'</em><small>'+time+'</small></div>'}).join('');
 $('gp-tyre').textContent=RaceWeekend.TYRES[p.tyre].name+' · '+Math.round((1-p.wear)*100)+'%';$('gp-pit-call').textContent=p.pit?'PIT ASSIST':p.requested?'BOX THIS LAP':'P / RB · BOX';$('gp-next-tyre').textContent='T / LB · '+RaceWeekend.TYRES[GP.pitChoice].name;$('gp-strategy-status').textContent=qual?'FINISH YOUR LAP AFTER THE FLAG':w.cfg.twoCompounds?(p.used.size>=2?'COMPOUND RULE MET':'USE TWO COMPOUNDS'):'OPEN STRATEGY';$('gp-pit-call').classList.toggle('called',p.requested);}
function gpResults(retired=false){const w=GP.weekend;if(!w)return;state='results';keys.clear();$('hud').hidden=true;const qual=w.phase==='qualifying-result',order=qual?w.grid.map(id=>w.drivers[id]):w.classification();const position=order.findIndex(d=>d.id===0)+1;let buttons='';if(qual){if(w.cfg.qualifying==='full'&&w.stage<2)buttons='<button class="p" id="gp-next">'+(w.player.active?'NEXT: Q'+(w.stage+2):'COMPLETE QUALIFYING')+'</button>';else buttons='<button class="p" id="gp-to-race">TO THE GRID</button>'}else buttons='<button class="p" id="gp-rematch">RACE AGAIN</button>';
 $('rb').innerHTML='<div class="eyebrow">'+CIRCUIT.name+'</div><h2>'+(qual?'Qualifying':retired?'Retired':'Race result')+'</h2><div class="gp-result-position">'+(w.player.dsq?'DSQ':'P'+position)+'</div><p>'+(qual?'Grid order is set by valid timed laps.':w.player.dsq?'Two different dry compounds were required.':w.player.penalty?'Includes '+w.player.penalty+' seconds in penalties.':'MR 26 · '+w.difficulty.name)+'</p><div class="gp-results-scroll"><table><thead><tr><th>POS</th><th>DRIVER</th><th>'+(qual?'BEST LAP':'TIME / GAP')+'</th><th>'+(qual?'STATUS':'STOPS')+'</th></tr></thead><tbody>'+order.map((d,i)=>'<tr class="'+(d.id===0?'you':'')+'"><td>'+(d.dsq?'DSQ':i+1)+'</td><td>'+d.name+'</td><td>'+(qual?fmt(d.best*1000):d.retired?'DNF':d.finished?fmt((d.finishTime+d.penalty)*1000):'RUNNING')+'</td><td>'+(qual?(d.active?'ADVANCED':'ELIMINATED'):d.stops)+'</td></tr>').join('')+'</tbody></table></div>'+buttons+'<button data-ov="menu" id="gp-back">MAIN MENU</button>';show('results');if($('gp-next'))$('gp-next').onclick=()=>{if(w.player.active)startWeekend('qual',true);else{while(w.stage<2){w.startQual(w.stage+1);let guard=0;while(w.phase==='qualifying'&&guard++<600000)w.update(.1);w.events=[]}gpResults()}};if($('gp-to-race'))$('gp-to-race').onclick=()=>{audioInit();startWeekend('gp',true)};if($('gp-rematch'))$('gp-rematch').onclick=()=>startWeekend('gp');$('gp-back').onclick=clearWeekend;}
$('gp-pit-call').onclick=gpPitRequest;$('gp-next-tyre').onclick=gpCycleTyre;
document.addEventListener('click',e=>{const m=e.target.closest('[data-weekend]');if(m){mode=m.dataset.weekend;show('weekend');$('weekend-heading').textContent=mode==='qual'?'QUALIFYING':'RACE'}});
$('gp-start').onclick=()=>{audioInit();refreshGuideSpeeds();startWeekend(mode==='qual'?'qual':'gp')};

const normalWeekendHud=hud;hud=function(){normalWeekendHud();if(GP.weekend)gpHud(true)};

let lastGpContact=-10;function gpContact(){const w=GP.weekend;if(!w||w.clock-lastGpContact<.4)return;for(const d of w.drivers.slice(1)){if(d.pit||d.finished)continue;let along=RaceWeekend.mod(d.progress-w.player.progress+LEN/2,LEN)-LEN/2;if(Math.abs(along)>5.2)continue;const p=gpTrackPose(d),lateral=(c.x-p.x)*-Math.sin(c.h)+(c.z-p.z)*Math.cos(c.h);if(Math.abs(lateral)>1.65)continue;lastGpContact=w.clock;if(along>0)c.vx=Math.min(c.vx,d.v*.9);else d.v=Math.min(d.v,c.vx*.92);rumble(.25,.5,120);msg('CAR CONTACT',800);break}}

document.addEventListener('click',e=>{if(e.target.closest('[data-ov="menu"]')&&GP.weekend)clearWeekend()});const baseWeekendMenu=$('tomenu').onclick;$('tomenu').onclick=()=>{clearWeekend();baseWeekendMenu()};

// Authentic supplied artwork; every placement is attached to circuit infrastructure.
const sponsorAudit=[];
window.sponsorReady=(async()=>{
 const data=[{"name": "STEM Racing", "file": "01_e586d257-e9ab-431f-ab7b-9b0907f41d26.png", "bounds": [0, 0, 354, 177], "size": [354, 177], "sha256": "2299756672e72eb1abc3cf105bd04b65dc05fd90a4453acc766d7f7b806b3181", "image": "/assets/2299756672e72eb1abc3.png"}, {"name": "Hustle Hive", "file": "03_418d3c02-3a3f-4acb-9daf-0253f751b5a6.png", "bounds": [102, 117, 490, 281], "size": [612, 408], "sha256": "702949edd75cb0d8b27d7033a42faa9e5bb325cd45beae5976abcde347d3769e", "image": "/assets/702949edd75cb0d8b27d.png"}, {"name": "Brinda's", "file": "04_41ec5ae6-346f-479e-b1ae-46b2d18f6d9b.png", "bounds": [38, 92, 368, 200], "size": [413, 292], "sha256": "93d0bdd054083142d4925f13018157d7dea80af63934537697807d0be3f96b92", "image": "/assets/93d0bdd054083142d492.png"}, {"name": "Enermax Synergy", "file": "05_7263300e-4d38-449c-a0bb-b13bb4627161.png", "bounds": [44, 42, 367, 240], "size": [403, 264], "sha256": "8b50e8339f2fff4a8af35c103c3162235913e962eb1f15481df23a1848ab80b1", "image": "/assets/8b50e8339f2fff4a8af3.png"}, {"name": "NPE Print Communications", "file": "06_e5e7a2e8-4b8d-40ae-8674-ec915d418e45.png", "bounds": [41, 147, 406, 299], "size": [447, 447], "sha256": "4cd99c22b8b711637dac721b04569de83872c0ed07a36396f3f5c76954dee665", "image": "/assets/4cd99c22b8b711637dac.png"}, {"name": "Axis", "file": "07_9a0a22cb-62d9-4df0-bfbf-ac329d85f163.png", "bounds": [107, 100, 371, 429], "size": [500, 500], "sha256": "f71e04d3563f9686a03d3b751e4771b86781e4ab9fd014185bd5439605bfeb3a", "image": "/assets/f71e04d3563f9686a03d.png"}],loaded=await Promise.all(data.map(a=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve({a,im});im.onerror=()=>reject(Error(a.name+' artwork unavailable'));im.src=a.image})));
 function texture(brand,aspect=4){const {a,im}=loaded[brand],b=a.bounds,t=canvasTex(1536,Math.round(1536/aspect),(ctx,w,h)=>{ctx.fillStyle=brand===2?'#101b32':'#edeee8';ctx.fillRect(0,0,w,h);const scale=Math.min(w*.82/(b[2]-b[0]),h*.82/(b[3]-b[1]));const dw=(b[2]-b[0])*scale,dh=(b[3]-b[1])*scale;ctx.drawImage(im,b[0],b[1],b[2]-b[0],b[3]-b[1],(w-dw)/2,(h-dh)/2,dw,dh)});t.anisotropy=Math.min(16,ren.capabilities.getMaxAnisotropy());return t}
 const textures=data.map((_,i)=>texture(i)),materials=textures.map(map=>new T.MeshStandardMaterial({map,roughness:.76,metalness:0,emissiveMap:map,emissive:0xffffff,emissiveIntensity:isNight?.10:0,side:T.DoubleSide}));
 function audit(brand,kind,station,side){sponsorAudit.push({name:data[brand].name,sha256:data[brand].sha256,kind,station,side})}
 function wrap(brand,start,metres,side){const count=Math.round(metres/(LEN/N)),P=[],UV=[];let distance=0;
 for(let n=0;n<count;n++){const i=(start+n+N)%N,j=(i+1)%N,a=trackBarrier(i,side)-side*.035,b=trackBarrier(j,side)-side*.035;const A=[cx[i]+nx[i]*a,surfaceHeight(i,a)+.07,cz[i]+nz[i]*a],B=[cx[j]+nx[j]*b,surfaceHeight(j,b)+.07,cz[j]+nz[j]*b],ds=Math.hypot(B[0]-A[0],B[2]-A[2]);for(const [p,top,u]of[[A,0,distance],[B,0,distance+ds],[B,1,distance+ds],[A,0,distance],[B,1,distance+ds],[A,1,distance]]){P.push(p[0],p[1]+top*1.05,p[2]);UV.push((side>0?-1:1)*u/4.6,top)}distance+=ds}
 const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(P,3));geo.setAttribute('uv',new T.Float32BufferAttribute(UV,2));geo.computeVertexNormals();const map=textures[brand].clone();map.wrapS=T.RepeatWrapping;map.needsUpdate=true;const mat=materials[brand].clone();mat.map=mat.emissiveMap=map;const mesh=new T.Mesh(geo,mat);mesh.receiveShadow=true;mesh.name=data[brand].name+' wall wrap';scene.add(mesh);audit(brand,'flush barrier wrap',start,side)}
 function panel(brand,parent,x,y,z,w,h,rotation=0,kind='pit facade'){const mat=materials[brand].clone();mat.side=T.FrontSide;const m=new T.Mesh(new T.PlaneGeometry(w,h),mat);m.position.set(x,y,z);m.rotation.y=rotation;m.receiveShadow=true;parent.add(m);audit(brand,kind,0,0);return m}
 for(let i=0;i<6;i++){wrap(i,Math.round((.035+i*.157)*N),urban?50:105,i%2?1:-1);panel(i,pitGroup,-53+i*20,9.1,2.8,17,3.5,0,'pit building fascia');}
 // Gantries have supports behind the barrier and generous road clearance.
 for(const [f,brand]of[[.012,0],[venuePlan.bridge,5]]){const i=Math.round(f*N),left=trackBarrier(i,-1)-2,right=trackBarrier(i,1)+2,span=right-left,g=new T.Group();g.position.set(cx[i],cy[i],cz[i]);g.rotation.y=-Math.atan2(tz[i],tx[i])-Math.PI/2;scene.add(g);const legs=[[left,4.5,0,.45,9,.55],[right,4.5,0,.45,9,.55],[(left+right)/2,8.5,0,span,.65,.85]];instanceBoxes(g,venueMetal,legs,true,false);panel(brand,g,0,8.15,-.46,Math.min(span,29),2.7,Math.PI,'overhead bridge fascia');panel(brand,g,0,8.15,.46,Math.min(span,29),2.7,0,'overhead bridge fascia');}
 // Flat runoff stencils: verify each corner stays outside the racing surface and inside the wall.
 if(!urban)for(const [fraction,brand]of[[.20,1],[.47,2],[.67,3],[.87,4]]){const i=Math.round(fraction*N),side=CIRCUIT.line.curvature[i]>0?-1:1,space=Math.abs(trackBarrier(i,side))-W;if(space<15)continue;const off=side*(W+Math.min(space/2,16)),x=cx[i]+nx[i]*off,z=cz[i]+nz[i]*off;let valid=true;for(const f of[-8,8])for(const a of[-3,3]){const xx=x+tx[i]*f+nx[i]*a,zz=z+tz[i]*f+nz[i]*a,p=prog(xx,zz,i);if(Math.abs(p.d)<W+2||Math.abs(p.d)>Math.abs(trackBarrier(p.i,side))-2)valid=false}if(!valid)continue;const m=new T.Mesh(new T.PlaneGeometry(16,6),materials[brand]);m.rotation.set(-Math.PI/2,0,Math.atan2(tz[i],tx[i]));m.position.set(x,surfaceHeight(i,off)+.045,z);m.receiveShadow=true;scene.add(m);audit(brand,'runoff stencil',i,side)}
 return sponsorAudit;
})();

// Three r128 does not calculate instance bounds. Give each immutable batch its
// real local-space bounds; otherwise a whole circuit is submitted every pass.
const batchAudit={bounded:0,tiles:0,instances:0,mergedDrawBatches:0,sharedDetailDrawsSaved:0};
function boundInstances(mesh){
 const geometry=mesh.geometry.clone(),matrix=new T.Matrix4(),box=new T.Box3(),one=new T.Box3();
 geometry.computeBoundingBox();const base=geometry.boundingBox.clone();
 for(let i=0;i<mesh.count;i++){mesh.getMatrixAt(i,matrix);box.union(one.copy(base).applyMatrix4(matrix))}
 geometry.boundingBox=box;geometry.boundingSphere=box.getBoundingSphere(new T.Sphere());
 mesh.geometry=geometry;mesh.frustumCulled=true;batchAudit.bounded++;batchAudit.instances+=mesh.count;
}
function finalizeSceneryBatches(){
 // The guide and foliage move every frame; fixed bounds would make them vanish
 // after driving away from the origin. Only immutable scenery is consolidated.
 scene.updateMatrixWorld(true);const shared=new Map(),source=[];
 // Identical static props retain their geometry, materials and world transforms
 // while sharing a draw call. Explicit tagging keeps cars and moving effects out.
 const details=new Map();scene.traverseVisible(o=>{if(o.isMesh&&!o.isInstancedMesh&&o.userData.staticArchitecture&&!Array.isArray(o.material)&&!o.material.transparent){const key=[o.geometry.uuid,o.material.uuid,o.castShadow,o.receiveShadow,o.renderOrder,Math.floor(o.matrixWorld.elements[12]/220),Math.floor(o.matrixWorld.elements[14]/220)].join(':');if(!details.has(key))details.set(key,[]);details.get(key).push(o)}});
 for(const objects of details.values()){if(objects.length<2)continue;const o=objects[0],mesh=new T.InstancedMesh(o.geometry,o.material,objects.length);mesh.name='Shared static venue detail';mesh.castShadow=o.castShadow;mesh.receiveShadow=o.receiveShadow;mesh.renderOrder=o.renderOrder;objects.forEach((p,i)=>mesh.setMatrixAt(i,p.matrixWorld));scene.add(mesh);objects.forEach(p=>p.parent.remove(p));batchAudit.sharedDetailDrawsSaved+=objects.length-1;}
 scene.traverse(o=>{if(o.isInstancedMesh&&o.visible&&o.geometry===unitBox&&!o.material.transparent){source.push(o);const matrix=new T.Matrix4(),color=new T.Color();for(let i=0;i<o.count;i++){o.getMatrixAt(i,matrix);matrix.premultiply(o.matrixWorld);const key=[o.material.uuid,!!o.instanceColor,o.castShadow,o.receiveShadow,o.renderOrder,Math.floor(matrix.elements[12]/220),Math.floor(matrix.elements[14]/220)].join(':');if(!shared.has(key))shared.set(key,{source:o,entries:[]});if(o.instanceColor)o.getColorAt(i,color);shared.get(key).entries.push({matrix:matrix.clone(),color:o.instanceColor?color.clone():null})}}});
 for(const {source:o,entries} of shared.values()){const m=new T.InstancedMesh(unitBox,o.material,entries.length);m.name='Static architecture tile';m.castShadow=o.castShadow;m.receiveShadow=o.receiveShadow;m.renderOrder=o.renderOrder;entries.forEach((e,i)=>{m.setMatrixAt(i,e.matrix);if(e.color)m.setColorAt(i,e.color)});scene.add(m)}
 for(const o of source)o.parent.remove(o);batchAudit.mergedDrawBatches=source.length-shared.size;
 const list=[];scene.traverse(o=>{if(o.isInstancedMesh&&o.visible&&!o.name.startsWith('3D vegetation')&&o!==farTree&&o!==farTrunks&&o!==guideArrows&&o!==guideOutline)list.push(o)});
 for(const mesh of list){
  if(mesh.parent!==scene||mesh.count<128){boundInstances(mesh);continue}
  const groups=new Map(),matrix=new T.Matrix4(),color=new T.Color();
  for(let i=0;i<mesh.count;i++){mesh.getMatrixAt(i,matrix);const k=Math.floor(matrix.elements[12]/220)+','+Math.floor(matrix.elements[14]/220);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(i)}
  if(groups.size<2){boundInstances(mesh);continue}
  const parent=new T.Group();parent.name=mesh.name+' spatial tiles';parent.position.copy(mesh.position);parent.quaternion.copy(mesh.quaternion);parent.scale.copy(mesh.scale);
  for(const ids of groups.values()){const tile=new T.InstancedMesh(mesh.geometry,mesh.material,ids.length);tile.name=mesh.name+' tile';tile.castShadow=mesh.castShadow;tile.receiveShadow=mesh.receiveShadow;tile.renderOrder=mesh.renderOrder;
   ids.forEach((id,j)=>{mesh.getMatrixAt(id,matrix);tile.setMatrixAt(j,matrix);if(mesh.instanceColor){mesh.getColorAt(id,color);tile.setColorAt(j,color)}});boundInstances(tile);parent.add(tile);batchAudit.tiles++}
  scene.add(parent);scene.remove(mesh);
 }
}
finalizeSceneryBatches();

// Grand Prix edition shell. URL invites, quality presets, install and fullscreen stay keyboard-accessible.
const gpTools=document.createElement('div');gpTools.className='gp-tools';gpTools.innerHTML='<label for="graphics-quality">GRAPHICS</label><select id="graphics-quality"><option value="ultra">Ultra</option><option value="high">High</option><option value="performance">Performance</option></select><button id="install-game" hidden>Install game</button><a href="https://game.milanoracing.team/?multiplayer=1" target="_blank" rel="noopener">Online grid ↗</a>';
$('graphics-settings').append(gpTools);$('graphics-quality').value=graphicsPreset;$('graphics-quality').onchange=e=>applyGraphics(e.target.value);
applyGraphics(graphicsPreset);
const title=document.querySelector('#menu h1');if(title)title.innerHTML='MILANO<b>RACING</b>';
const tourSubtitle=document.querySelector('#circuits .small');if(tourSubtitle)tourSubtitle.textContent='12 circuits. One grid.';
document.title='Milano Racing · Grand Prix';
const style=document.createElement('style');style.textContent='.gp-tools{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:22px;padding-top:15px;border-top:1px solid #ffffff22}.gp-tools label{font:700 10px Arial;letter-spacing:.15em;color:#97a5b8}.gp-tools select{max-width:150px;background:#101828;color:#fff;padding:9px;border:1px solid #414c60}.gp-tools a{font-size:12px;color:#ff9c40}.circuit-card.selected{border-color:#ff7a00}#circuit-grid{max-height:55vh;overflow-y:auto}.status-error:empty{display:none}#network-browse{display:grid;gap:8px;margin-top:14px}#network-browse button{display:flex;justify-content:space-between;gap:16px}#network-ping{font-size:11px}';document.head.append(style);
let installPrompt;addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install-game').hidden=false});$('install-game').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('install-game').hidden=true}};
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('/sw.js').catch(()=>{});
// A strict-origin message API allows the parent Milano site to pause and select a venue.
addEventListener('message',e=>{if(!['https://milanoracing.team','https://www.milanoracing.team',location.origin].includes(e.origin)||e.source!==parent)return;const m=e.data;if(m?.type==='milano:pause')pause();if(m?.type==='milano:circuit'&&CIRCUITS[m.id]&&!MP.active)chooseCircuit(m.id)});
if(parent!==window)for(const origin of['https://milanoracing.team','https://www.milanoracing.team'])parent.postMessage({type:'milano:ready',circuits:Object.keys(CIRCUITS)},origin);
window.MilanoBuild={version:'grand-prix-1',circuits:12,rendering:graphics,getDiagnostics:()=>({circuit:CIRCUIT.id,webgl2:ren.capabilities.isWebGL2,drawCalls:ren.info.render.calls,triangles:ren.info.render.triangles,textures:ren.info.memory.textures,quality:graphicsPreset,guide:racingGuide.report?.time})};

// Keep incomplete terrain textures out of the first playable frame.
window.MilanoReady=false;
(async()=>{await document.fonts.ready;await window.sponsorReady;const start=performance.now();while(!sceneAssetsLoaded&&performance.now()-start<45000)await new Promise(r=>setTimeout(r,50));if(sceneAssetErrors.length||!sceneAssetsLoaded){$('load-progress').textContent='A circuit asset did not finish loading.';$('load-retry').hidden=false;return}window.MilanoReady=true;$('scene-loading').hidden=true})().catch(error=>{$('load-progress').textContent='The circuit could not finish loading.';$('load-retry').hidden=false;console.error(error)});
